// === Tab: getPoints ===
let directions = [
    [1, 0],
    [0, -1],
    [0, 1],
    [-1, 0],
]

function getPoints() {
	let [x, y] = P.startPoint 
	let points = [[x, y]] 
	let edges = {} 
	let xMax = P.innerGrid 
	let yMax = P.innerGrid 

	const getEdges = (x, y) => {
			let key = `${x}-${y}`
			if (!edges[key]) {
					edges[key] = []
			}
			return edges[key]
	}

    let i = 0
    let pointsCount = 0
    let needToPushPoint1 = false
    while (i < P.edgesAttempts && pointsCount < P.edgesMax) {
        let visited = getEdges(x, y)
        let options = [...directions].filter(([xd, yd]) => {
            if (x + xd < 0 || x + xd > xMax) return false
            if (y + yd < 0 || y + yd > yMax) return false
            if (visited.find(([vx, vy]) => vx === x + xd && vy === y + yd)) return false
            return true
        })

        if (options.length === 0) {
            x = Math.floor(Math.random() * (xMax + 1))
            y = Math.floor(Math.random() * (yMax + 1))
            i++
            points.push(false)
            points.push([x, y])
            continue
        }

        if (needToPushPoint1) {
            points.push([x, y])
            needToPushPoint1 = false
            pointsCount++
        }
        let prevX = x
        let prevY = y

        let dir = random(options)
        x += dir[0]
        y += dir[1]
        visited.push([x, y])
        getEdges(x, y).push([prevX, prevY])
        points.push([x, y])
        pointsCount++
        i++

        if (i % P.edgesBreak === 0) {
            points.push(false)
            x = Math.floor(Math.random() * (xMax + 1))
            y = Math.floor(Math.random() * (yMax + 1))
            needToPushPoint1 = true
        }
    }	

		return { points, edges }
}

// === Tab: getFaces ===
function graphPoints(edges, gridSize) {
	let map = {}
	for (let xi = 0; xi < gridSize; xi++) {
		for (let yi = 0; yi < gridSize; yi++) {
			let key = `${xi}-${yi}`
			let edgestl = edges[`${xi}-${yi}`]
			let edgestr = edges[`${xi + 1}-${yi}`]
			let edgesbl = edges[`${xi}-${yi + 1}`]

			map[key] = {
				x: xi,
				y: yi,
				visited: false,
				right: null,
				left: null,
				up: null,
				down: null,
			}

			// find line above
			let aboveLine = edgestl?.find(([x, y]) => x === xi + 1 && y === yi)
			if (!aboveLine) {
				map[key].up = `${xi}-${yi - 1}`
			}

			let leftLine = edgestl?.find(([x, y]) => x === xi && y === yi + 1)
			if (!leftLine) {
				map[key].left = `${xi - 1}-${yi}`
			}

			// find line right
			let rightLine = edgestr?.find(([x, y]) => x === xi + 1 && y === yi + 1)
			if (!rightLine) {
				map[key].right = `${xi + 1}-${yi}`
			}

			// find line bottom
			let bottomLine = edgesbl?.find(([x, y]) => x === xi + 1 && y === yi + 1)
			if (!bottomLine) {
				map[key].down = `${xi}-${yi + 1}`
			}
		}
	}

	return map
}

function getFaces(edges, gridSize) {
	let map = graphPoints(edges, gridSize)

	let x = 0
	let y = 0
	let queue = [`${x}-${y}`]
	let currentFace = []
	let faces = []
	let currentEnclosed = true


	while (queue.length > 0) {
		let current = queue.shift()
		let node = map[current]

		if (node && !node.visited) {
			let vals = current.split('-')
			currentFace.push([+vals[0], +vals[1]])

			if (node.right && map[node.right] && !map[node.right].visited) {
				queue.push(node.right)
			}
			if (node.left && map[node.left] && !map[node.left].visited) {
				queue.push(node.left)
			}
			if (node.up && map[node.up] && !map[node.up].visited) {
				queue.push(node.up)
			}
			if (node.down && map[node.down] && !map[node.down].visited) {
				queue.push(node.down)
			}

			if (node.y === gridSize - 1 && node.down) {
				currentEnclosed = false
			}

			if (node.x === gridSize - 1 && node.right) {
				currentEnclosed = false
			}

			node.visited = true
		}

		if (queue.length === 0) {
			if (currentFace.length) {
				faces.push({
					cells: currentFace,
					enclosed: currentEnclosed
				})
			}
			currentEnclosed = true
			currentFace = []
			if (x < gridSize - 1) {
				x++
				queue.push(`${x}-${y}`)
			} else if (y < gridSize - 1) {
				y++
				x = 0
				queue.push(`${x}-${y}`)
			}
		}
	}

	return faces

}

// === Tab: mySketch ===
let P = {
	tiles: 6,
	padding: 0.18,
	edgesMax: 18,
	edgesAttempts: 24,
	edgesBreak: 3,
	innerGrid: 3,
	startPoint: [0,0],
	symmetry: 'reflect'
}

let black = "#080708"
let white = "#e6e8e6"
let palette = ["#3772ff", "#df2935", "#fdca40"]
let pointsData
let facesData

function isCheckered(x, y) {
	let xIsEven = (x % 2 === 0)
	let yIsEven = (y % 2 === 0)
	return ((xIsEven && !yIsEven) || (yIsEven && !xIsEven))
}

function quadrant(points, faces, size, turn) {
	let step = size / P.innerGrid

	faces.forEach((face) => {
		if ( face.enclosed && face.cells.length < 5 ) {
			let [x, y] = face.cells[0]
			let checkered = isCheckered(x, y)
			noStroke()
			if (x + y === 3) {
				fill(palette[2])
			} else if (x + y === 2) {
				fill(palette[1])
			} else if (!checkered) {
				fill(palette[0])
			} else {
				noFill()
			}
			face.cells.forEach(([x, y]) => {
				rect(x * step - 1, y * step - 1, step + 2)
			})
		}
	})
	strokeWeight(2)
	stroke('#fff')
	for (let i = 1; i < points.length; i++) {
		let p1 = points[i - 1]
		let p2 = points[i]
		if (p1 === false || p2 === false) continue
		let [x1, y1] = p1
		let [x2, y2] = p2
		line(x1 * step, y1 * step, x2 * step, y2 * step)
	}


}

function mirroredQuadrants(points, faces, size) {
	let step = size / 2
	push()
	translate(step, step)
	if (P.symmetry === 'reflect') {
		scale(1, -1)
		quadrant(points, faces, step, 1)
		scale(1, -1)
		quadrant(points, faces, step, 2)
		scale(-1, 1)
		quadrant(points, faces, step, 3)
		scale(1, -1)
		quadrant(points, faces, step, 4)
	} else if (P.symmetry === 'rotate') {
		quadrant(points, faces, step, 1)
		rotate(Math.PI / 2)
		quadrant(points, faces, step, 2)
		rotate(Math.PI / 2)
		quadrant(points, faces, step, 3)
		rotate(Math.PI / 2)
		quadrant(points, faces, step, 4)
	}
	pop()
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	pointsData = []
	strokeCap(PROJECT)
	for (let i = 0; i < P.tiles ** 2; i++) {
		let pts = getPoints()
		let faces = getFaces(pts.edges, P.innerGrid)
		pointsData.push({
			lines: pts,
			faces
		})
	}

	noLoop()
}

function draw() {
	background('#121212')
	let m = max(width, height) * 0.85
	push()
	translate((width - m) / 2, (height - m) / 2)
	let blockStep = m / P.tiles
	let padding = blockStep * P.padding
	let blockSize = blockStep - padding * 2
	pointsData.forEach(({
		lines,
		faces
	}, i) => {
		let points = lines.points
		let x = i % P.tiles
		let y = floor(i / P.tiles)
		push()
		translate(x * blockStep + padding, y * blockStep + padding)
		mirroredQuadrants(points, faces, blockSize)
		pop()
	})
	pop()
}

function windowResized() {
	resizeCanvas(window.innerWidth, window.innerHeight)
	redraw()
}

function mousePressed() {
	pointsData = []
	for (let i = 0; i < P.tiles ** 2; i++) {
		let pts = getPoints()
		let faces = getFaces(pts.edges, P.innerGrid)
		pointsData.push({
			lines: pts,
			faces
		})
	}
	redraw()
}

